package com.valor.installation;

import com.valor.auth.*;
import com.valor.notifications.NotificationService;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @Transactional
class InstallationProposalService {
 private final InstallationProposalRepository proposals; private final InstallationRequestRepository requests; private final AssetIdentityAccess access; private final WorkflowIdentityAccess identities; private final AuditService audit; private final NotificationService notifications;
 InstallationProposalService(InstallationProposalRepository p,InstallationRequestRepository r,AssetIdentityAccess a,WorkflowIdentityAccess i,AuditService au,NotificationService n){proposals=p;requests=r;access=a;identities=i;audit=au;notifications=n;}
 List<View> history(Long id){access.requireAdmin();return proposals.findByRequestIdOrderByCreatedAtDescIdDesc(id).stream().map(this::view).toList();}
 View customer(Long id){return customerHistory(id).stream().findFirst().orElse(null);}
 List<View> customerHistory(Long id){var c=identities.customer(access.actor());requests.findByIdAndCustomerId(id,c.getId()).orElseThrow(InstallationProposalService::denied);return proposals.findCustomerHistory(id).stream().map(this::customerView).toList();}
 View save(Long id,Write in){access.requireAdmin();var r=request(id);if(!SetOf.editable(r.getStatus()))throw conflict("Requirements must be reviewed before preparing a proposal");InstallationProposal p;
  if(in.id()==null){p=new InstallationProposal();p.setVersion(proposals.maxVersion(id)+1);}
  else {p=proposals.findById(in.id()).orElseThrow(()->conflict("Proposal not found"));if(p.getRequest()!=null&&!p.getRequest().getId().equals(id))throw denied();if(p.getStatus()!=ProposalStatus.DRAFT)throw conflict("Presented and decided proposals are immutable; create a revision");if(in.version()!=null&&!in.version().equals(p.getVersion()))throw conflict("Proposal changed; refresh and try again");}
  p.setRequest(r);p.setAmount(in.amount());p.setCurrency(clean(in.currency())==null?"INR":clean(in.currency()).toUpperCase());p.setScope(clean(in.scope()));p.setNotes(clean(in.notes()));p.setTerms(clean(in.terms()));p.setValidUntil(in.validUntil());p.setCreatedBy(access.actor());p.setStatus(ProposalStatus.DRAFT);var saved=proposals.saveAndFlush(p);audit.record("INSTALLATION_PROPOSAL_SAVE","INSTALLATION_PROPOSAL",saved.getId(),"Installation proposal saved");return view(saved);}
 View present(Long id,long version){access.requireAdmin();var p=proposal(id);if(!p.getVersion().equals(version)||p.getStatus()!=ProposalStatus.DRAFT)throw conflict("Proposal changed or is not a draft");if(p.getRequest().getStatus()!=InstallationStatus.PROPOSAL_READY&&p.getRequest().getStatus()!=InstallationStatus.REQUIREMENTS_REVIEW&&p.getRequest().getStatus()!=InstallationStatus.PROPOSAL_DECLINED)throw conflict("Requirements review is required before presenting a proposal");p.setStatus(ProposalStatus.PRESENTED);p.setPresentedAt(LocalDateTime.now());p.getRequest().setStatus(InstallationStatus.PROPOSAL_READY);proposals.saveAndFlush(p);audit.record("INSTALLATION_PROPOSAL_PRESENT","INSTALLATION_PROPOSAL",p.getId(),"Installation proposal presented");notifications.createSystemOnce(p.getRequest().getCustomer().getUser().getId(),"INSTALLATION_PROPOSAL_PRESENTED:"+p.getId()+":"+p.getVersion(),"Installation proposal ready","Your new lift installation proposal is ready to review.");return view(p);}
 View decide(Long id,boolean accepted,String notes,Long expectedVersion){var c=identities.customer(access.actor());var p=proposal(id);if(!p.getRequest().getCustomer().getId().equals(c.getId()))throw denied();if(expectedVersion!=null&&!expectedVersion.equals(p.getVersion()))throw conflict("Proposal has changed; refresh before deciding");if(p.getStatus()!=ProposalStatus.PRESENTED)throw conflict("Only a presented proposal can be decided");if(p.getValidUntil()!=null&&p.getValidUntil().isBefore(LocalDateTime.now())){p.setStatus(ProposalStatus.EXPIRED);proposals.saveAndFlush(p);throw conflict("This proposal has expired");}p.setStatus(accepted?ProposalStatus.ACCEPTED:ProposalStatus.DECLINED);p.setDecidedAt(LocalDateTime.now());p.setDecisionNotes(clean(notes));p.getRequest().setStatus(accepted?InstallationStatus.PROPOSAL_ACCEPTED:InstallationStatus.PROPOSAL_DECLINED);proposals.saveAndFlush(p);notifications.createSystemOnce(c.getUser().getId(),"INSTALLATION_PROPOSAL_DECIDED:"+p.getId()+":"+p.getVersion(),accepted?"Proposal accepted":"Proposal declined",accepted?"Your installation proposal was accepted.":"Your installation proposal was declined.");return customerView(p);}
 View start(Long id,long version){access.requireAdmin();var r=request(id);if(r.getVersion()!=version||r.getStatus()!=InstallationStatus.PROPOSAL_ACCEPTED)throw conflict("Customer acceptance is required before construction");r.setStatus(InstallationStatus.IN_PROGRESS);r.setConstructionStartedAt(LocalDateTime.now());requests.saveAndFlush(r);audit.record("INSTALLATION_CONSTRUCTION_START","INSTALLATION_REQUEST",id,"Installation construction started");return proposals.findTopByRequestIdOrderByCreatedAtDescIdDesc(id).map(this::view).orElse(null);}
 void reviewRequirements(Long id,String req,long version){access.requireAdmin();var r=request(id);if(r.getVersion()!=version)throw conflict("Installation changed; refresh and try again");if(r.getStatus()!=InstallationStatus.SUBMITTED&&r.getStatus()!=InstallationStatus.ASSESSMENT_SUBMITTED&&r.getStatus()!=InstallationStatus.REQUIREMENTS_REVIEW)throw conflict("Requirements cannot be reviewed in this state");r.setAdminRequirements(clean(req));r.setRequirementsReviewedAt(LocalDateTime.now());r.setRequirementsReviewedBy(access.actor());r.setStatus(InstallationStatus.REQUIREMENTS_REVIEW);requests.saveAndFlush(r);audit.record("INSTALLATION_REQUIREMENTS_REVIEW","INSTALLATION_REQUEST",id,"Admin requirements reviewed");}
 View complete(Long id,long version){access.requireAdmin();var r=request(id);if(r.getVersion()!=version||r.getStatus()!=InstallationStatus.IN_PROGRESS)throw conflict("Installation is not in progress");r.setStatus(InstallationStatus.COMPLETED);r.setCompletedAt(LocalDateTime.now());requests.saveAndFlush(r);audit.record("INSTALLATION_COMPLETE","INSTALLATION_REQUEST",id,"Installation completed");return proposals.findTopByRequestIdOrderByCreatedAtDescIdDesc(id).map(this::view).orElse(null);}
 private InstallationRequest request(Long id){return requests.findById(id).orElseThrow(()->new IllegalArgumentException("Installation not found"));} private InstallationProposal proposal(Long id){return proposals.findById(id).orElseThrow(()->new IllegalArgumentException("Proposal not found"));} private View customerView(InstallationProposal p){return new View(p.getId(),p.getRequest().getId(),p.getAmount(),p.getCurrency(),p.getScope(),p.getNotes(),p.getTerms(),p.getValidUntil(),p.getStatus(),p.getVersion(),p.getPresentedAt(),p.getDecidedAt(),p.getDecisionNotes());} private View view(InstallationProposal p){return customerView(p);} private static String clean(String s){return s==null||s.isBlank()?null:s.trim();} private static IllegalStateException conflict(String s){return new IllegalStateException(s);} private static AccessDeniedException denied(){return new AccessDeniedException("Access denied");}
 record View(Long id,Long installationRequestId,BigDecimal amount,String currency,String scope,String notes,String terms,LocalDateTime validUntil,ProposalStatus status,Long version,LocalDateTime presentedAt,LocalDateTime decidedAt,String decisionNotes){}
 record Write(Long id,BigDecimal amount,String currency,String scope,String notes,String terms,LocalDateTime validUntil,Long version){}
 static final class SetOf{static boolean editable(InstallationStatus s){return s==InstallationStatus.REQUIREMENTS_REVIEW||s==InstallationStatus.PROPOSAL_READY||s==InstallationStatus.PROPOSAL_DECLINED;}}
}
